weights = {"temperature": 0.3, "rain": -4.0, "wind": -0.5}
bias = -6.0


def neuron(inputs, bias):
    total = sum(weights[name] * value for name, value in inputs.items()) + bias
    return total, ("beach!" if total > 0 else "stay home")


days = {
    "hot and calm": {"temperature": 32, "rain": 0, "wind": 2},
    "hot but rainy": {"temperature": 31, "rain": 1, "wind": 2},
    "mild and windy": {"temperature": 24, "rain": 0, "wind": 6},
}
for name, inputs in days.items():
    total, decision = neuron(inputs, bias)
    parts = " + ".join(f"{weights[k]}*{v}" for k, v in inputs.items())
    print(f"{name:15} {parts} + ({bias}) = {total:5.1f} -> {decision}")

print()
for b in (-8.0, -6.0, -3.0):
    total, decision = neuron(days["mild and windy"], b)
    print(f"bias {b:5}: mild and windy -> {total:5.1f} {decision}")

