import math

def relu(x):
    return max(0, x)

def sigmoid(x):
    return 1 / (1 + math.exp(-x))

def descend(w, lr, steps):
    for _ in range(steps):
        w = w - lr * 2 * (w - 3)
    return round(w, 4)
